-- =====================================================================
-- RipassoAI — 0009: 30 domande per LangChain e per Skill e agenti AI
--   LangChain:        2 già presenti + 28 nuove
--   Skill e agenti:   4 già presenti + 26 nuove
--   Chiude il monte di 300 domande (30 per argomento).
-- =====================================================================

select public.importa_quiz('langchain', $j$[
  {"livello":"L1","testo":"Che cos'è un embedding?","spiegazione":"È un vettore di numeri che rappresenta il significato di un testo: testi simili finiscono vicini nello spazio vettoriale.","opzioni":["Un vettore numerico che rappresenta il significato del testo","Un file compresso con il testo originale","Un indice alfabetico delle parole","Un formato di prompt"],"corretta":0},
  {"livello":"L1","testo":"Quale classe del modulo si usa per invocare un modello chat OpenAI?","spiegazione":"ChatOpenAI è il wrapper del modello chat; si configura con model, temperature, timeout e maxRetries.","opzioni":["ChatOpenAI","OpenAIChatModel","ChatModelOpenAI","OpenAICompletion"],"corretta":0},
  {"livello":"L1","testo":"A cosa serve ChatPromptTemplate?","spiegazione":"Costruisce un prompt con messaggi di sistema e umani e variabili riempibili a ogni invocazione.","opzioni":["A costruire prompt con messaggi e variabili riutilizzabili","A memorizzare le risposte in cache","A creare il vector store","A validare lo schema JSON"],"corretta":0},
  {"livello":"L1","testo":"Cosa fa StringOutputParser in una catena?","spiegazione":"Converte la risposta del modello in una stringa semplice, pronta per l'uso o per lo step successivo.","opzioni":["Converte l'output del modello in una stringa","Divide il testo in chunk","Genera gli embedding","Valida il JSON"],"corretta":0},
  {"livello":"L1","testo":"Cosa fa RecursiveCharacterTextSplitter?","spiegazione":"Divide i documenti in chunk rispettando una gerarchia di separatori, dal paragrafo fino al singolo carattere.","opzioni":["Divide i documenti in chunk usando separatori in ordine","Genera gli embedding dei documenti","Ordina i documenti per data","Comprime i documenti"],"corretta":0},
  {"livello":"L1","testo":"Che caratteristica ha MemoryVectorStore?","spiegazione":"Tiene i vettori in memoria nel processo: è comodo per esperimenti, non adatto alla produzione.","opzioni":["Tiene i vettori in memoria nel processo","Persiste su PostgreSQL","È un database distribuito","Cifra i vettori su disco"],"corretta":0},
  {"livello":"L1","testo":"Cosa permette withStructuredOutput?","spiegazione":"Fa restituire al modello un oggetto conforme a uno schema Zod, invece di testo libero.","opzioni":["Ottenere un oggetto conforme a uno schema","Comprimere il prompt","Creare un vector store","Dividere i documenti"],"corretta":0},
  {"livello":"L1","testo":"Cosa indica temperature vicina a 0?","spiegazione":"Riduce la casualità: le risposte diventano più ripetibili e adatte a generazione verificabile.","opzioni":["Risposte più deterministiche e ripetibili","Risposte più creative e varie","Nessuna chiamata al modello","Output solo in JSON"],"corretta":0},

  {"livello":"L2","testo":"Cosa indicano chunkSize e chunkOverlap?","spiegazione":"chunkSize è la dimensione del blocco, chunkOverlap quanti caratteri si ripetono tra un blocco e il successivo.","opzioni":["Dimensione del chunk e caratteri condivisi tra chunk adiacenti","Numero di documenti e numero di embedding","Timeout e numero di retry","Token di input e token di output"],"corretta":0},
  {"livello":"L2","testo":"Cosa fa asRetriever({ k: 4 }) su un vector store?","spiegazione":"Espone il vector store come retriever che restituisce i 4 chunk più simili alla query.","opzioni":["Restituisce i 4 chunk più simili alla query","Genera 4 risposte diverse","Crea 4 indici","Limita a 4 token"],"corretta":0},
  {"livello":"L2","testo":"In cosa differisce una catena RAG da un semplice prompt?","spiegazione":"Il RAG recupera prima i passaggi rilevanti dai documenti e li inserisce nel contesto della richiesta.","opzioni":["Recupera documenti rilevanti e li inserisce nel contesto","Usa solo modelli più grandi","Non richiede una chiave API","Funziona senza prompt"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve RunnablePassthrough in una catena RAG?","spiegazione":"Passa la domanda originale allo step successivo senza modificarla, accanto al contesto recuperato.","opzioni":["Passa la domanda originale allo step successivo","Scarta la domanda","Genera gli embedding","Ordina i chunk"],"corretta":0},
  {"livello":"L2","testo":"Perché si valida l'output del modello con Zod?","spiegazione":"Tipi, lunghezze e indici vengono controllati prima dell'uso: il programma non si rompe con output non conforme.","opzioni":["Controlla tipi e vincoli prima di usare i dati","Riduce i token inviati","Crea il prompt di sistema","Sostituisce il modello"],"corretta":0},
  {"livello":"L2","testo":"Cosa controlla l'espressione new Set(opzioni).size !== 4?","spiegazione":"Verifica che le quattro opzioni siano distinte: un set elimina i duplicati e riduce la dimensione.","opzioni":["Che le opzioni siano quattro valori distinti","Che l'indice della risposta sia 4","Che ci siano quattro domande","Che il livello sia 4"],"corretta":0},
  {"livello":"L2","testo":"Cosa contiene metadata in un Document di LangChain?","spiegazione":"Metadati come fonte, argomento e livello, utili per citare e filtrare i chunk recuperati.","opzioni":["Informazioni come fonte, argomento e livello","Il testo completo del documento","Gli embedding del documento","Le chiavi API"],"corretta":0},

  {"livello":"L3","testo":"Perché in produzione non si usa MemoryVectorStore?","spiegazione":"Vive nella memoria del processo: si perde al riavvio e non è condiviso tra istanze.","opzioni":["Si perde al riavvio e non è condiviso tra istanze","Non supporta gli embedding","Non accetta più di 10 documenti","Non permette le query"],"corretta":0},
  {"livello":"L3","testo":"Perché si usa un chunkOverlap maggiore di zero?","spiegazione":"Evita di spezzare una frase informativa a cavallo del confine, mantenendo il contesto in entrambi i chunk.","opzioni":["Evita che un'informazione a cavallo del confine vada persa","Riduce il numero di token","Velocizza gli embedding","Elimina i duplicati"],"corretta":0},
  {"livello":"L3","testo":"Perché il giudizio di un modello validatore non è una verità assoluta?","spiegazione":"È un secondo modello con gli stessi limiti: riduce gli errori ma richiede approvazione umana.","opzioni":["È un altro modello con gli stessi limiti e serve comunque revisione umana","Perché non conosce il contesto","Perché non può leggere il JSON","Perché costa troppo"],"corretta":0},
  {"livello":"L3","testo":"Perché la cache si chiave su (argomento, livello, versione prompt, modello)?","spiegazione":"La stessa richiesta deve riusare la stessa risposta solo se cambiano né i vincoli né il modello.","opzioni":["Solo con gli stessi vincoli e lo stesso modello la risposta è riutilizzabile","Per occupare più spazio su disco","Per aggirare il rate limit","Per cifrare i dati"],"corretta":0},
  {"livello":"L3","testo":"Perché la generazione massiva va spostata in un job batch o in coda?","spiegazione":"Non deve bloccare la richiesta HTTP: il job procede in background e l'utente riceve l'esito dopo.","opzioni":["Per non bloccare la richiesta HTTP dell'utente","Per usare meno token","Per evitare la validazione","Per disattivare i log"],"corretta":0},
  {"livello":"L3","testo":"Perché separare istruzioni e contenuto con delimitatori espliciti?","spiegazione":"Rende riconoscibile al modello cosa è comando e cosa è documento, riducendo il prompt injection.","opzioni":["Il modello distingue comandi da contenuto non fidato","Riduce il numero di token","Migliora la velocità degli embedding","Abilita il caching"],"corretta":0},
  {"livello":"L3","testo":"A cosa servono i metadati sui chunk nella pipeline di ingestion?","spiegazione":"Permettono citazioni verificabili e filtri per argomento, livello e tenant durante il retrieval.","opzioni":["Citazioni verificabili e filtri per argomento, livello e tenant","A comprimere i documenti","A generare le chiavi API","A ordinare le risposte"],"corretta":0},

  {"livello":"L4","testo":"Perché il multi-tenant richiede filtri sul retriever?","spiegazione":"Senza filtro sui metadati del tenant una scuola potrebbe recuperare documenti di un'altra.","opzioni":["Senza filtro si possono recuperare documenti di un altro tenant","Per ridurre i costi di embedding","Per velocizzare il modello","Per evitare il caching"],"corretta":0},
  {"livello":"L4","testo":"Perché non dare tool distruttivi a un agente senza conferma umana?","spiegazione":"Un errore o un prompt injection potrebbe cancellare o modificare dati: serve una conferma esplicita.","opzioni":["Un errore o un'iniezione potrebbe cancellare dati","I tool distruttivi sono più lenti","Non producono log","Consumano troppi token"],"corretta":0},
  {"livello":"L4","testo":"Perché loggare token e costo stimato per ogni job?","spiegazione":"Rende il costo per quiz noto, permette budget e alert e individua le richieste più care.","opzioni":["Rende noto il costo per quiz e abilita budget e alert","Aumenta la qualità delle risposte","Riduce la latenza","Cifra i prompt"],"corretta":0},
  {"livello":"L4","testo":"Perché lo schema di output limita i danni di un prompt injection?","spiegazione":"Anche se il modello esegue istruzioni iniettate, l'output deve comunque rispettare il formato atteso.","opzioni":["L'output deve comunque rispettare il formato previsto","Il modello non legge i documenti","Il prompt viene cifrato","Il contesto viene svuotato"],"corretta":0},
  {"livello":"L4","testo":"Perché la re-ingestion deve essere idempotente?","spiegazione":"Ripetere l'import non deve creare chunk duplicati: si confrontano fonte e contenuto prima di inserire.","opzioni":["Ripetere l'import non deve creare chunk duplicati","Deve cancellare il vector store","Deve rigenerare le chiavi API","Deve ignorare i metadati"],"corretta":0},
  {"livello":"L4","testo":"Perché serve un eval set con risposte attese?","spiegazione":"Senza casi di riferimento non si misura se una modifica al prompt o al modello peggiora il tutor.","opzioni":["Permette di misurare se una modifica peggiora il tutor","Sostituisce la revisione umana","Riduce i costi di embedding","Genera gli indici"],"corretta":0}
]$j$::jsonb);

select public.importa_quiz('agenti-ai', $j$[
  {"livello":"L1","testo":"Che cos'è una skill in questo contesto?","spiegazione":"È un pacchetto versionato di istruzioni, esempi e criteri che insegna a svolgere un compito ricorrente.","opzioni":["Un pacchetto versionato di istruzioni e criteri per un compito ricorrente","Un prompt scritto una volta e dimenticato","Un plugin del browser","Un modello di linguaggio"],"corretta":0},
  {"livello":"L1","testo":"Quale file contiene istruzioni e contratto di una skill?","spiegazione":"SKILL.md raccoglie quando usarla, input, regole, output e criteri di qualità.","opzioni":["SKILL.md","README.json","prompt.txt","index.js"],"corretta":0},
  {"livello":"L1","testo":"Quali campi stanno nel frontmatter di SKILL.md?","spiegazione":"name, description e version identificano la skill e ne dichiarano lo scopo.","opzioni":["name, description, version","token, costo, latenza","id, password, ruolo","input, output, database"],"corretta":0},
  {"livello":"L1","testo":"Che cos'è un tool per un agente?","spiegazione":"Una funzione con nome, descrizione e schema che l'agente può scegliere di chiamare.","opzioni":["Una funzione con nome, descrizione e schema chiamabile dall'agente","Un file di configurazione del modello","Un tipo di prompt","Un database vettoriale"],"corretta":0},
  {"livello":"L1","testo":"A cosa serve la description di un tool?","spiegazione":"Spiega al modello quando e perché usare quel tool, guidando la scelta dell'azione.","opzioni":["Spiega al modello quando usare quel tool","Imposta il timeout della funzione","Definisce i permessi del database","Cifra i parametri"],"corretta":0},
  {"livello":"L1","testo":"Quale libreria del modulo modella un agente come grafo di nodi e stato?","spiegazione":"LangGraph usa StateGraph e Annotation per definire nodi, stato e transizioni.","opzioni":["LangGraph","Express","Prisma","Zod"],"corretta":0},
  {"livello":"L1","testo":"Cosa significa human-in-the-loop?","spiegazione":"Una persona approva o corregge le azioni e gli output prima che diventino definitivi.","opzioni":["Una persona approva o corregge prima della pubblicazione","Il modello gira su hardware umano","L'utente scrive il prompt a mano","Il sistema non ha automazioni"],"corretta":0},

  {"livello":"L2","testo":"Qual è la regola d'oro sull'utenteId passato a un tool?","spiegazione":"Deve arrivare dalla sessione autenticata, mai dal testo prodotto dal modello.","opzioni":["Deve arrivare dalla sessione, non dal testo del modello","Deve essere scelto dal modello","Deve essere scritto nel prompt","Deve essere pubblico"],"corretta":0},
  {"livello":"L2","testo":"Qual è il ciclo tipico di un agente?","spiegazione":"Percezione, piano, azione e osservazione si ripetono fino alla risposta finale o al limite di passi.","opzioni":["Percezione, piano, azione, osservazione","Compilazione, test, deploy","Prompt, embedding, cache","Login, query, logout"],"corretta":0},
  {"livello":"L2","testo":"Quando NON serve un agente?","spiegazione":"Quando basta una catena deterministica: meno autonomia significa più sicurezza e prevedibilità.","opzioni":["Quando basta una catena deterministica","Quando servono dati aggiornati","Quando il percorso non è noto","Quando ci sono più azioni possibili"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve model.bindTools(tools)?","spiegazione":"Dichiara al modello quali tool può chiamare, lasciando a lui la scelta dell'azione.","opzioni":["Dichiara al modello i tool disponibili","Esegue subito tutti i tool","Crea gli embedding","Valida l'output"],"corretta":0},
  {"livello":"L2","testo":"A cosa serve il reducer in Annotation di LangGraph?","spiegazione":"Definisce come combinare il valore precedente con quello nuovo restituito da un nodo.","opzioni":["Definisce come combinare valore precedente e nuovo","Imposta il timeout del nodo","Crea il database","Filtra i tool"],"corretta":0},
  {"livello":"L2","testo":"Cosa deve restituire il nodo tool quando il tool richiesto non esiste?","spiegazione":"Un messaggio di tool non disponibile con lo stesso tool_call_id, così il modello può reagire.","opzioni":["Un messaggio di errore con lo stesso tool_call_id","Nessuna risposta","Una nuova chiamata al modello","Un'eccezione non gestita"],"corretta":0},
  {"livello":"L2","testo":"Che ruolo ha il critico in un'orchestrazione generatore-critico-validatore?","spiegazione":"Rivede l'output del generatore e segnala errori prima della validazione automatica e umana.","opzioni":["Rivede l'output e segnala gli errori","Genera gli embedding","Salva nel database","Scrive il frontend"],"corretta":0},

  {"livello":"L3","testo":"Perché meno autonomia dell'agente significa più sicurezza?","spiegazione":"Meno scelte libere riducono le azioni impreviste e rendono il comportamento più prevedibile e verificabile.","opzioni":["Riduce le azioni impreviste e rende il comportamento verificabile","Aumenta la creatività del modello","Riduce i costi di embedding","Velocizza il database"],"corretta":0},
  {"livello":"L3","testo":"Perché una skill va versionata e testata?","spiegazione":"È un artefatto riutilizzabile: versione e test permettono di misurarne le regressioni nel tempo.","opzioni":["Per misurare le regressioni e riusarla in modo affidabile","Per aumentare i token","Per evitare la revisione umana","Per cifrare il prompt"],"corretta":0},
  {"livello":"L3","testo":"Perché delimitare il contenuto non fidato in un prompt?","spiegazione":"Il modello distingue istruzioni e documenti e può ignorare i comandi nascosti nel testo.","opzioni":["Per distinguere istruzioni e documenti e ignorare comandi nascosti","Per ridurre la latenza","Per generare embedding migliori","Per evitare il rate limit"],"corretta":0},
  {"livello":"L3","testo":"Perché chiedere al modello di dichiarare l'incertezza invece di imporgli di essere sicuro?","spiegazione":"Un'incertezza dichiarata è informazione utile; la sicurezza forzata produce risposte inventate.","opzioni":["L'incertezza dichiarata è informazione utile, la sicurezza forzata produce invenzioni","Perché riduce i token","Perché è richiesto da Zod","Perché semplifica il caching"],"corretta":0},
  {"livello":"L3","testo":"Perché limitare i passi e i tool disponibili a un agente?","spiegazione":"Evita cicli infiniti, costi fuori controllo e accessi ad azioni non necessarie.","opzioni":["Evita cicli infiniti, costi eccessivi e azioni non necessarie","Aumenta la memoria del modello","Migliora il frontend","Riduce il numero di tabelle"],"corretta":0},
  {"livello":"L3","testo":"Perché separare generatore, critico e validatore?","spiegazione":"Ogni ruolo ha un compito ristretto: è più semplice misurare e correggere ciascuno stadio.","opzioni":["Compiti ristretti sono più semplici da misurare e correggere","Per usare meno modelli","Per evitare il contesto","Per ridurre le tabelle"],"corretta":0},

  {"livello":"L4","testo":"Perché la pubblicazione richiede approvazione umana e audit trail?","spiegazione":"Nessun output automatico è affidabile al 100%: serve una decisione tracciabile di chi approva.","opzioni":["Serve una decisione tracciabile perché nessun output è affidabile al 100%","Per ridurre i token","Per velocizzare la pubblicazione","Per evitare gli embedding"],"corretta":0},
  {"livello":"L4","testo":"Un agente deve interrogare il database: qual è la mitigazione corretta?","spiegazione":"Esporre tool ristretti e parametrizzati, con permessi minimi e query read-only quando basta.","opzioni":["Tool ristretti e parametrizzati con permessi minimi","Lasciargli eseguire SQL libero","Dargli la password del database nel prompt","Disattivare i log"],"corretta":0},
  {"livello":"L4","testo":"Perché misurare costi e latenza per tenant?","spiegazione":"Permette budget e alert per cliente e individua abusi o query troppo costose.","opzioni":["Permette budget e alert per cliente e individua abusi","Aumenta la qualità del modello","Riduce il numero di tool","Cifra le risposte"],"corretta":0},
  {"livello":"L4","testo":"Perché serve un test cross-tenant sul retriever?","spiegazione":"Verifica che le query di un tenant non recuperino mai documenti di un altro.","opzioni":["Verifica che non si recuperino documenti di un altro tenant","Misura la latenza del modello","Conta i token","Valida lo schema JSON"],"corretta":0},
  {"livello":"L4","testo":"Perché le decisioni di revisione alimentano un dataset di valutazione?","spiegazione":"Approvazioni, modifiche e rifiuti diventano esempi per misurare e migliorare la pipeline.","opzioni":["Diventano esempi per misurare e migliorare la pipeline","Servono a cancellare le domande","Sostituiscono il database","Riducono i costi di embedding"],"corretta":0},
  {"livello":"L4","testo":"Perché non inserire segreti nel contesto del modello?","spiegazione":"Il contenuto può essere riportato nell'output o esfiltrato da un prompt injection.","opzioni":["Possono finire nell'output o essere esfiltrati da un'iniezione","Aumentano i token","Rallentano il retrieval","Impediscono il caching"],"corretta":0}
]$j$::jsonb);
